BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Pacemakers & ICDs' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Pacemakers & ICDs', 'Device indications, troubleshooting, and chest pain priorities', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Pacemakers and ICDs (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Pacemakers and ICDs - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Pacemaker definition" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Pacemaker definition" is most accurate?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "Pacemakers are used to raise blood volume directly."}, {"id": "c", "text": "Assess rhythm response and perfusion after pacing initiation."}, {"id": "d", "text": "First-degree block is the only mandatory pacing indication."}]'::jsonb, '["c"]'::jsonb, 'Correct because A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction. Assess rhythm response and perfusion after pacing initiation.', 'Pacemakers and ICDs - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Temporary vs permanent pacing" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Temporary vs permanent pacing" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Permanent pacemakers are external bedside-only."}, {"id": "b", "text": "Permanent systems are implanted under skin."}, {"id": "c", "text": "Temporary pacing is lifelong default therapy."}, {"id": "d", "text": "Arm restriction is unnecessary after implant."}]'::jsonb, '["b"]'::jsonb, 'Correct because Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin. Match pacing type to acute versus chronic rhythm support needs.', 'Pacemakers and ICDs - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Bradycardia indication" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Bradycardia indication" in Pacemakers & ICDs?', '[{"id": "a", "text": "Failure to pace shows spike with no QRS."}, {"id": "b", "text": "Asymptomatic tachycardia is primary pacing indication."}, {"id": "c", "text": "Arc welding is recommended with pacemakers."}, {"id": "d", "text": "<60 bpm threshold appears in note context."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm. Treat symptomatic low-rate states to prevent syncope and hypoperfusion.', 'Pacemakers and ICDs - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Heart block indication" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Heart block indication" in Pacemakers & ICDs?', '[{"id": "a", "text": "High-grade AV block should trigger prompt pacing preparedness."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "First-degree block is the only mandatory pacing indication."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pacemaker indications include second-degree type II and third-degree AV block. High-grade AV block should trigger prompt pacing preparedness.', 'Pacemakers and ICDs - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Other pacing indications" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Other pacing indications" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Pacemaker use is excluded after cardiac surgery."}, {"id": "b", "text": "Recognize broader pacing use beyond simple bradycardia."}, {"id": "c", "text": "Aggressive overhead arm exercise is encouraged immediately."}, {"id": "d", "text": "Failure to pace is normal after implantation."}]'::jsonb, '["b"]'::jsonb, 'Correct because Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis. Recognize broader pacing use beyond simple bradycardia.', 'Pacemakers and ICDs - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "ECG post-implant monitoring" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "ECG post-implant monitoring" is most accurate?', '[{"id": "a", "text": "Exercise immediately after shock is advised."}, {"id": "b", "text": "Failure to capture means no spike present."}, {"id": "c", "text": "Spikes indicate malfunction by default."}, {"id": "d", "text": "Pacing spikes should be visible/appropriate."}]'::jsonb, '["d"]'::jsonb, 'Correct because Nursing care includes ECG monitoring to verify pacing spikes and appropriate response. Correlate spikes with electrical/mechanical outcomes continuously.', 'Pacemakers and ICDs - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pacing threshold" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Pacing threshold" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Threshold has no relation to pacing effectiveness."}, {"id": "b", "text": "Threshold refers to minimum effective current."}, {"id": "c", "text": "Arm restriction is unnecessary after implant."}, {"id": "d", "text": "Threshold is the maximum tolerated blood pressure."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pacing threshold is the lowest current needed to pace the heart. Optimize threshold to ensure reliable capture with minimal energy.', 'Pacemakers and ICDs - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Failure to pace" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Failure to pace" in Pacemakers & ICDs?', '[{"id": "a", "text": "Failure to pace is normal after implantation."}, {"id": "b", "text": "Arc welding is recommended with pacemakers."}, {"id": "c", "text": "Repeated shocks can be ignored if conscious."}, {"id": "d", "text": "No pacing spike can indicate failure to pace."}]'::jsonb, '["d"]'::jsonb, 'Correct because Failure to pace is identified by absence of pacing spike when one is expected. Recognize no-spike failure quickly to prevent brady-asystolic events.', 'Pacemakers and ICDs - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Failure to capture" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Failure to capture" in Pacemakers & ICDs?', '[{"id": "a", "text": "Exercise immediately after shock is advised."}, {"id": "b", "text": "Medications are given before ABC assessment."}, {"id": "c", "text": "Spike followed by QRS always indicates failure."}, {"id": "d", "text": "Spike without QRS defines failure to capture."}]'::jsonb, '["d"]'::jsonb, 'Correct because Failure to capture is pacing spike without resulting QRS complex. Spike-no-QRS pattern requires urgent evaluation of lead/output issues.', 'Pacemakers and ICDs - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Arm movement restriction" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Arm movement restriction" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Post-op mobility guidance is part of nursing care."}, {"id": "b", "text": "Aggressive overhead arm exercise is encouraged immediately."}, {"id": "c", "text": "Arm restriction is unnecessary after implant."}, {"id": "d", "text": "ICD does not treat ventricular arrhythmias."}]'::jsonb, '["a"]'::jsonb, 'Correct because After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement. Protect lead position in early post-op period.', 'Pacemakers and ICDs - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Electromagnetic precautions" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Electromagnetic precautions" is most accurate?', '[{"id": "a", "text": "Arc welding is recommended with pacemakers."}, {"id": "b", "text": "Exercise immediately after shock is advised."}, {"id": "c", "text": "Repeated shocks can be ignored if conscious."}, {"id": "d", "text": "Strong electromagnetic fields should be avoided."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment). Prevent device interference through exposure counseling.', 'Pacemakers and ICDs - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Patient ID and symptom reporting" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Patient ID and symptom reporting" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Device identification is unnecessary in emergencies."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Hiccups can signal diaphragm stimulation/lead displacement."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope. Early symptom reporting can identify displacement or pacing failure.', 'Pacemakers and ICDs - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "ICD function" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "ICD function" in Pacemakers & ICDs?', '[{"id": "a", "text": "ICD is indicated for sudden death risk patients."}, {"id": "b", "text": "Repeated shocks can be ignored if conscious."}, {"id": "c", "text": "ICD does not treat ventricular arrhythmias."}, {"id": "d", "text": "Sit upright is best for hypotensive shock."}]'::jsonb, '["a"]'::jsonb, 'Correct because ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia. Use ICD in patients at risk for sudden cardiac death from lethal ventricular rhythms.', 'Pacemakers and ICDs - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "If ICD fires" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "If ICD fires" in Pacemakers & ICDs?', '[{"id": "a", "text": "Medications are given before ABC assessment."}, {"id": "b", "text": "Lie down after ICD discharge is recommended."}, {"id": "c", "text": "Exercise immediately after shock is advised."}, {"id": "d", "text": "12-lead ECG can be delayed several hours."}]'::jsonb, '["b"]'::jsonb, 'Correct because If ICD fires, patient should lie down, note time, and notify provider if symptoms continue. Post-shock self-management reduces injury and ensures urgent follow-up.', 'Pacemakers and ICDs - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Bystander sensation with ICD" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Bystander sensation with ICD" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Education reduces fear around ICD events."}, {"id": "b", "text": "ICD discharge is fatal to bystanders."}, {"id": "c", "text": "Pericarditis is best managed flat supine."}, {"id": "d", "text": "Flat Trendelenburg is best for HF/SOB."}]'::jsonb, '["a"]'::jsonb, 'Correct because People touching the patient during ICD discharge may feel mild shock that is not dangerous. Provide reassurance to family and staff to reduce panic during discharge events.', 'Pacemakers and ICDs - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "ICD storm emergency" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "ICD storm emergency" is most accurate?', '[{"id": "a", "text": "Storm implies unstable arrhythmia burden."}, {"id": "b", "text": "High-sodium canned foods are recommended."}, {"id": "c", "text": "ICD storm is routine expected function."}, {"id": "d", "text": "Sit upright is best for hypotensive shock."}]'::jsonb, '["a"]'::jsonb, 'Correct because Repeated ICD firing should be reported immediately as an emergency (ICD storm). Escalate recurrent shocks urgently for rhythm stabilization.', 'Pacemakers and ICDs - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Chest pain initial priorities" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Chest pain initial priorities" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "b", "text": "Medications are given before ABC assessment."}, {"id": "c", "text": "Oxygen threshold is O2 sat <90% in note."}, {"id": "d", "text": "12-lead ECG can be delayed several hours."}]'::jsonb, '["c"]'::jsonb, 'Correct because Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes. Rapid physiologic stabilization and STEMI detection are first-line priorities.', 'Pacemakers and ICDs - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Chest pain workflow continuation" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Chest pain workflow continuation" in Pacemakers & ICDs?', '[{"id": "a", "text": "Establish access and objective diagnostics while initiating evidence-based medication sequence."}, {"id": "b", "text": "No labs are needed for chest pain."}, {"id": "c", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "d", "text": "Magnetic field precautions are optional and have no device implications."}]'::jsonb, '["a"]'::jsonb, 'Correct because Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin. Establish access and objective diagnostics while initiating evidence-based medication sequence.', 'Pacemakers and ICDs - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Nitroglycerin safety" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Nitroglycerin safety" in Pacemakers & ICDs?', '[{"id": "a", "text": "Recent sildenafil is contraindication."}, {"id": "b", "text": "High-sodium canned foods are recommended."}, {"id": "c", "text": "Pacemakers only deliver defibrillation shocks."}, {"id": "d", "text": "Sildenafil timing has no relevance."}]'::jsonb, '["a"]'::jsonb, 'Correct because Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours. Prevent severe hypotension from contraindicated nitrate administration.', 'Pacemakers and ICDs - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Positioning HF/SOB" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Positioning HF/SOB" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "b", "text": "Breathing relief is rationale for elevated HOB."}, {"id": "c", "text": "Post-op position should always be Trendelenburg."}, {"id": "d", "text": "Permanent pacemakers are external bedside-only."}]'::jsonb, '["b"]'::jsonb, 'Correct because For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing. Use positioning to improve oxygenation while other therapies are prepared.', 'Pacemakers and ICDs - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Positioning hypotension/shock" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Positioning hypotension/shock" is most accurate?', '[{"id": "a", "text": "Sit upright is best for hypotensive shock."}, {"id": "b", "text": "Trendelenburg is preferred for all hypotension."}, {"id": "c", "text": "Asymptomatic tachycardia is primary pacing indication."}, {"id": "d", "text": "Positioning is an early supportive intervention."}]'::jsonb, '["d"]'::jsonb, 'Correct because For hypotension/shock, position supine with legs elevated 15–30° to increase venous return. Use immediate non-pharmacologic perfusion support while treating cause.', 'Pacemakers and ICDs - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Cardiogenic shock position caution" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Cardiogenic shock position caution" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Pacemakers only deliver defibrillation shocks."}, {"id": "b", "text": "Trendelenburg is first-line for cardiogenic shock."}, {"id": "c", "text": "Trendelenburg is avoided in cardiogenic shock."}, {"id": "d", "text": "Cardiogenic shock requires sitting upright always."}]'::jsonb, '["c"]'::jsonb, 'Correct because For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg. Balance BP support with cardiopulmonary tolerance in cardiogenic states.', 'Pacemakers and ICDs - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Pericarditis and post-op positioning" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Pericarditis and post-op positioning" in Pacemakers & ICDs?', '[{"id": "a", "text": "Pacemaker use is excluded after cardiac surgery."}, {"id": "b", "text": "Post-op position should always be Trendelenburg."}, {"id": "c", "text": "Trendelenburg is preferred for all hypotension."}, {"id": "d", "text": "Pericarditis relieved by sit up and leaning forward."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion. Condition-specific positioning can reduce pain and improve ventilation.', 'Pacemakers and ICDs - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Lifestyle diet teaching" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Lifestyle diet teaching" in Pacemakers & ICDs?', '[{"id": "a", "text": "Asymptomatic tachycardia is primary pacing indication."}, {"id": "b", "text": "High-sodium canned foods are recommended."}, {"id": "c", "text": "Processed foods/deli meats/canned soups are discouraged."}, {"id": "d", "text": "Pacemakers are used to raise blood volume directly."}]'::jsonb, '["c"]'::jsonb, 'Correct because Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods. Long-term dietary adherence reduces cardiovascular decompensation risk.', 'Pacemakers and ICDs - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lifestyle fluid/weight teaching" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Lifestyle fluid/weight teaching" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Threshold has no relation to pacing effectiveness."}, {"id": "b", "text": "Smoking cessation and weight-loss goals are included."}, {"id": "c", "text": "Threshold is the maximum tolerated blood pressure."}, {"id": "d", "text": "Unlimited fluids are advised for HF."}]'::jsonb, '["b"]'::jsonb, 'Correct because Lifestyle instructions include no smoking, weight loss if BMI >25, fluid restriction 1.5–2 L/day in HF, and daily weight reporting if gain >2 lb. Self-monitoring and fluid control detect and prevent worsening heart failure.', 'Pacemakers and ICDs - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "NCLEX perfusion tip" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "NCLEX perfusion tip" is most accurate?', '[{"id": "a", "text": "Failure to pace is normal after implantation."}, {"id": "b", "text": "Avoid Trendelenburg in hypotension is explicit tip."}, {"id": "c", "text": "Asymptomatic tachycardia is primary pacing indication."}, {"id": "d", "text": "Trendelenburg is preferred for all hypotension."}]'::jsonb, '["b"]'::jsonb, 'Correct because NCLEX tip emphasizes avoiding Trendelenburg for hypotension and prioritizing oxygenation/circulation first. Stabilize airway-breathing-circulation before noncritical steps.', 'Pacemakers and ICDs - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pacemaker definition" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Pacemaker definition" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Pacemakers deliver electrical impulses."}, {"id": "b", "text": "Spikes indicate malfunction by default."}, {"id": "c", "text": "Pacemakers only deliver defibrillation shocks."}, {"id": "d", "text": "AV block is contraindication to pacing."}]'::jsonb, '["a"]'::jsonb, 'Correct because A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction. Assess rhythm response and perfusion after pacing initiation.', 'Pacemakers and ICDs - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Temporary vs permanent pacing" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Temporary vs permanent pacing" in Pacemakers & ICDs?', '[{"id": "a", "text": "Temporary and permanent pacing have different use contexts."}, {"id": "b", "text": "Aggressive overhead arm exercise is encouraged immediately."}, {"id": "c", "text": "Permanent pacemakers are external bedside-only."}, {"id": "d", "text": "Threshold has no relation to pacing effectiveness."}]'::jsonb, '["a"]'::jsonb, 'Correct because Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin. Match pacing type to acute versus chronic rhythm support needs.', 'Pacemakers and ICDs - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Bradycardia indication" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Bradycardia indication" in Pacemakers & ICDs?', '[{"id": "a", "text": "Spikes indicate malfunction by default."}, {"id": "b", "text": "Arc welding is recommended with pacemakers."}, {"id": "c", "text": "Bradycardia is never paced."}, {"id": "d", "text": "Symptoms drive urgency for intervention."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm. Treat symptomatic low-rate states to prevent syncope and hypoperfusion.', 'Pacemakers and ICDs - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Heart block indication" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Heart block indication" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Pacemaker indications include second-degree type II and third-degree AV block."}, {"id": "d", "text": "First-degree block is the only mandatory pacing indication."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pacemaker indications include second-degree type II and third-degree AV block. High-grade AV block should trigger prompt pacing preparedness.', 'Pacemakers and ICDs - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Other pacing indications" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Other pacing indications" is most accurate?', '[{"id": "a", "text": "Pacemaker use is excluded after cardiac surgery."}, {"id": "b", "text": "Recognize broader pacing use beyond simple bradycardia."}, {"id": "c", "text": "Arm restriction is unnecessary after implant."}, {"id": "d", "text": "Failure to pace is normal after implantation."}]'::jsonb, '["b"]'::jsonb, 'Correct because Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis. Recognize broader pacing use beyond simple bradycardia.', 'Pacemakers and ICDs - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ECG post-implant monitoring" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "ECG post-implant monitoring" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "ECG monitoring is immediate post-implant priority."}, {"id": "b", "text": "Exercise immediately after shock is advised."}, {"id": "c", "text": "Spikes indicate malfunction by default."}, {"id": "d", "text": "Spike followed by QRS always indicates failure."}]'::jsonb, '["a"]'::jsonb, 'Correct because Nursing care includes ECG monitoring to verify pacing spikes and appropriate response. Correlate spikes with electrical/mechanical outcomes continuously.', 'Pacemakers and ICDs - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Pacing threshold" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Pacing threshold" in Pacemakers & ICDs?', '[{"id": "a", "text": "Aggressive overhead arm exercise is encouraged immediately."}, {"id": "b", "text": "Threshold is the maximum tolerated blood pressure."}, {"id": "c", "text": "Capture reliability depends on adequate output above threshold."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pacing threshold is the lowest current needed to pace the heart. Optimize threshold to ensure reliable capture with minimal energy.', 'Pacemakers and ICDs - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Failure to pace" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Failure to pace" in Pacemakers & ICDs?', '[{"id": "a", "text": "Arc welding is recommended with pacemakers."}, {"id": "b", "text": "ICD does not treat ventricular arrhythmias."}, {"id": "c", "text": "Failure to pace shows spike with no QRS."}, {"id": "d", "text": "Expected pacing without spike is abnormal."}]'::jsonb, '["d"]'::jsonb, 'Correct because Failure to pace is identified by absence of pacing spike when one is expected. Recognize no-spike failure quickly to prevent brady-asystolic events.', 'Pacemakers and ICDs - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Failure to capture" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Failure to capture" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Device identification is unnecessary in emergencies."}, {"id": "b", "text": "Spike followed by QRS always indicates failure."}, {"id": "c", "text": "Medications are given before ABC assessment."}, {"id": "d", "text": "Electrical output without depolarization is abnormal."}]'::jsonb, '["d"]'::jsonb, 'Correct because Failure to capture is pacing spike without resulting QRS complex. Spike-no-QRS pattern requires urgent evaluation of lead/output issues.', 'Pacemakers and ICDs - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Arm movement restriction" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Arm movement restriction" is most accurate?', '[{"id": "a", "text": "Protect lead position in early post-op period."}, {"id": "b", "text": "Arm restriction is unnecessary after implant."}, {"id": "c", "text": "ICD does not treat ventricular arrhythmias."}, {"id": "d", "text": "No one near patient feels anything."}]'::jsonb, '["a"]'::jsonb, 'Correct because After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement. Protect lead position in early post-op period.', 'Pacemakers and ICDs - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Electromagnetic precautions" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Electromagnetic precautions" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "ICD storm is routine expected function."}, {"id": "b", "text": "Exercise immediately after shock is advised."}, {"id": "c", "text": "Arc welding is recommended with pacemakers."}, {"id": "d", "text": "Device safety teaching includes environmental risks."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment). Prevent device interference through exposure counseling.', 'Pacemakers and ICDs - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Patient ID and symptom reporting" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Patient ID and symptom reporting" in Pacemakers & ICDs?', '[{"id": "a", "text": "Dizziness/syncope should be reported."}, {"id": "b", "text": "ICD discharge is fatal to bystanders."}, {"id": "c", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "d", "text": "Hiccups are always benign in this context."}]'::jsonb, '["a"]'::jsonb, 'Correct because Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope. Early symptom reporting can identify displacement or pacing failure.', 'Pacemakers and ICDs - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "ICD function" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "ICD function" in Pacemakers & ICDs?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "ICD does not treat ventricular arrhythmias."}, {"id": "c", "text": "Use ICD in patients at risk for sudden cardiac death from lethal ventricular rhythms."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["c"]'::jsonb, 'Correct because ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia. Use ICD in patients at risk for sudden cardiac death from lethal ventricular rhythms.', 'Pacemakers and ICDs - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "If ICD fires" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "If ICD fires" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Documenting shock time is recommended."}, {"id": "b", "text": "12-lead ECG can be delayed several hours."}, {"id": "c", "text": "Sildenafil timing has no relevance."}, {"id": "d", "text": "ICD firing never requires follow-up."}]'::jsonb, '["a"]'::jsonb, 'Correct because If ICD fires, patient should lie down, note time, and notify provider if symptoms continue. Post-shock self-management reduces injury and ensures urgent follow-up.', 'Pacemakers and ICDs - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Bystander sensation with ICD" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Bystander sensation with ICD" is most accurate?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "ICD discharge is fatal to bystanders."}, {"id": "d", "text": "Provide reassurance to family and staff to reduce panic during discharge events."}]'::jsonb, '["d"]'::jsonb, 'Correct because People touching the patient during ICD discharge may feel mild shock that is not dangerous. Provide reassurance to family and staff to reduce panic during discharge events.', 'Pacemakers and ICDs - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ICD storm emergency" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "ICD storm emergency" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "c", "text": "Repeated shocks can be ignored if conscious."}, {"id": "d", "text": "Escalate recurrent shocks urgently for rhythm stabilization."}]'::jsonb, '["d"]'::jsonb, 'Correct because Repeated ICD firing should be reported immediately as an emergency (ICD storm). Escalate recurrent shocks urgently for rhythm stabilization.', 'Pacemakers and ICDs - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Chest pain initial priorities" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Chest pain initial priorities" in Pacemakers & ICDs?', '[{"id": "a", "text": "ABCs come first in chest pain approach."}, {"id": "b", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "c", "text": "12-lead ECG can be delayed several hours."}, {"id": "d", "text": "Daily weight changes are irrelevant."}]'::jsonb, '["a"]'::jsonb, 'Correct because Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes. Rapid physiologic stabilization and STEMI detection are first-line priorities.', 'Pacemakers and ICDs - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Chest pain workflow continuation" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Chest pain workflow continuation" in Pacemakers & ICDs?', '[{"id": "a", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}, {"id": "b", "text": "No labs are needed for chest pain."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin."}]'::jsonb, '["d"]'::jsonb, 'Correct because Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin. Establish access and objective diagnostics while initiating evidence-based medication sequence.', 'Pacemakers and ICDs - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Nitroglycerin safety" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Nitroglycerin safety" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Prevent severe hypotension from contraindicated nitrate administration."}, {"id": "b", "text": "Sildenafil timing has no relevance."}, {"id": "c", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["a"]'::jsonb, 'Correct because Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours. Prevent severe hypotension from contraindicated nitrate administration.', 'Pacemakers and ICDs - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pacemakers & ICDs note, which statement about "Positioning HF/SOB" is most accurate?', 'According to the Pacemakers & ICDs note, which statement about "Positioning HF/SOB" is most accurate?', '[{"id": "a", "text": "Magnetic field precautions are optional and have no device implications."}, {"id": "b", "text": "Use positioning to improve oxygenation while other therapies are prepared."}, {"id": "c", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "d", "text": "Immediate reassessment is unnecessary when symptoms fluctuate briefly."}]'::jsonb, '["b"]'::jsonb, 'Correct because For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing. Use positioning to improve oxygenation while other therapies are prepared.', 'Pacemakers and ICDs - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Positioning hypotension/shock" in Pacemakers & ICDs. Which statement is correct?', 'The nurse is reviewing "Positioning hypotension/shock" in Pacemakers & ICDs. Which statement is correct?', '[{"id": "a", "text": "Positioning is an early supportive intervention."}, {"id": "b", "text": "High-sodium canned foods are recommended."}, {"id": "c", "text": "Asymptomatic tachycardia is primary pacing indication."}, {"id": "d", "text": "Sit upright is best for hypotensive shock."}]'::jsonb, '["a"]'::jsonb, 'Correct because For hypotension/shock, position supine with legs elevated 15–30° to increase venous return. Use immediate non-pharmacologic perfusion support while treating cause.', 'Pacemakers and ICDs - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiogenic shock position caution" in Pacemakers & ICDs?', 'Which clinical judgment is most accurate regarding "Cardiogenic shock position caution" in Pacemakers & ICDs?', '[{"id": "a", "text": "AV block is contraindication to pacing."}, {"id": "b", "text": "Trendelenburg is first-line for cardiogenic shock."}, {"id": "c", "text": "Cardiogenic shock requires sitting upright always."}, {"id": "d", "text": "Positioning differs from routine assumptions."}]'::jsonb, '["d"]'::jsonb, 'Correct because For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg. Balance BP support with cardiopulmonary tolerance in cardiogenic states.', 'Pacemakers and ICDs - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Pericarditis and post-op positioning" in Pacemakers & ICDs?', 'In rapid prioritization, which statement is most consistent with "Pericarditis and post-op positioning" in Pacemakers & ICDs?', '[{"id": "a", "text": "Pacemaker use is excluded after cardiac surgery."}, {"id": "b", "text": "Lung expansion is rationale for semi-Fowler post-op."}, {"id": "c", "text": "Post-op position should always be Trendelenburg."}, {"id": "d", "text": "Trendelenburg is preferred for all hypotension."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion. Condition-specific positioning can reduce pain and improve ventilation.', 'Pacemakers and ICDs - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lifestyle diet teaching" in Pacemakers & ICDs would the nurse recognize as correct?', 'Which conclusion about "Lifestyle diet teaching" in Pacemakers & ICDs would the nurse recognize as correct?', '[{"id": "a", "text": "Pacemakers are used to raise blood volume directly."}, {"id": "b", "text": "Pacemakers only deliver defibrillation shocks."}, {"id": "c", "text": "High-sodium canned foods are recommended."}, {"id": "d", "text": "Processed foods/deli meats/canned soups are discouraged."}]'::jsonb, '["d"]'::jsonb, 'Correct because Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods. Long-term dietary adherence reduces cardiovascular decompensation risk.', 'Pacemakers and ICDs - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Pacemaker definition" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Pacemaker definition" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Goal is adequate heart rate/perfusion."}, {"id": "b", "text": "Pacemakers deliver electrical impulses."}, {"id": "c", "text": "Device supports contraction when intrinsic rate is insufficient."}, {"id": "d", "text": "Pacemakers only deliver defibrillation shocks."}, {"id": "e", "text": "Pacemakers are used to raise blood volume directly."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction.', 'Pacemakers and ICDs - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Temporary vs permanent pacing"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Temporary vs permanent pacing"? (Select all that apply)', '[{"id": "a", "text": "Temporary and permanent pacing have different use contexts."}, {"id": "b", "text": "Permanent pacemakers are external bedside-only."}, {"id": "c", "text": "Permanent systems are implanted under skin."}, {"id": "d", "text": "Temporary pacing is lifelong default therapy."}, {"id": "e", "text": "Temporary pacing can be used post-MI."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin.', 'Pacemakers and ICDs - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Bradycardia indication" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Bradycardia indication" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "<60 bpm threshold appears in note context."}, {"id": "b", "text": "Bradycardia is never paced."}, {"id": "c", "text": "Symptoms drive urgency for intervention."}, {"id": "d", "text": "Symptomatic bradycardia is listed indication."}, {"id": "e", "text": "Asymptomatic tachycardia is primary pacing indication."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm.', 'Pacemakers and ICDs - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Heart block indication" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Heart block indication" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Third-degree block is listed indication."}, {"id": "b", "text": "First-degree block is the only mandatory pacing indication."}, {"id": "c", "text": "Second-degree type II block is listed indication."}, {"id": "d", "text": "Electrical signal interruption between atria and ventricles is emphasized."}, {"id": "e", "text": "AV block is contraindication to pacing."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pacemaker indications include second-degree type II and third-degree AV block.', 'Pacemakers and ICDs - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Other pacing indications" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Other pacing indications" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Sick sinus syndrome is listed indication."}, {"id": "b", "text": "Asystole with reversible cause is listed indication."}, {"id": "c", "text": "Post-cardiac surgery prophylaxis is listed use."}, {"id": "d", "text": "Pacemaker use is excluded after cardiac surgery."}, {"id": "e", "text": "Only ventricular tachycardia is paced."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis.', 'Pacemakers and ICDs - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "ECG post-implant monitoring" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "ECG post-implant monitoring" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Pacing spikes should be visible/appropriate."}, {"id": "b", "text": "Spikes indicate malfunction by default."}, {"id": "c", "text": "Rhythm verification is central to pacemaker safety."}, {"id": "d", "text": "ECG is unnecessary after implant."}, {"id": "e", "text": "ECG monitoring is immediate post-implant priority."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Nursing care includes ECG monitoring to verify pacing spikes and appropriate response.', 'Pacemakers and ICDs - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Pacing threshold"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Pacing threshold"? (Select all that apply)', '[{"id": "a", "text": "Threshold is the maximum tolerated blood pressure."}, {"id": "b", "text": "Threshold has no relation to pacing effectiveness."}, {"id": "c", "text": "Threshold refers to minimum effective current."}, {"id": "d", "text": "Capture reliability depends on adequate output above threshold."}, {"id": "e", "text": "Threshold assessment is listed nursing priority."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pacing threshold is the lowest current needed to pace the heart.', 'Pacemakers and ICDs - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Failure to pace" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Failure to pace" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "No pacing spike can indicate failure to pace."}, {"id": "b", "text": "Failure to pace is normal after implantation."}, {"id": "c", "text": "Expected pacing without spike is abnormal."}, {"id": "d", "text": "Immediate troubleshooting is required when no spike appears."}, {"id": "e", "text": "Failure to pace shows spike with no QRS."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Failure to pace is identified by absence of pacing spike when one is expected.', 'Pacemakers and ICDs - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Failure to capture" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Failure to capture" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Electrical output without depolarization is abnormal."}, {"id": "b", "text": "Spike without QRS defines failure to capture."}, {"id": "c", "text": "Capture failure threatens perfusion."}, {"id": "d", "text": "Failure to capture means no spike present."}, {"id": "e", "text": "Spike followed by QRS always indicates failure."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Failure to capture is pacing spike without resulting QRS complex.', 'Pacemakers and ICDs - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Arm movement restriction" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Arm movement restriction" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Arm restriction duration is 24–48 hours."}, {"id": "b", "text": "Post-op mobility guidance is part of nursing care."}, {"id": "c", "text": "Arm restriction is unnecessary after implant."}, {"id": "d", "text": "Reason is prevention of lead displacement."}, {"id": "e", "text": "Aggressive overhead arm exercise is encouraged immediately."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement.', 'Pacemakers and ICDs - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Electromagnetic precautions" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Electromagnetic precautions" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Arc welding is recommended with pacemakers."}, {"id": "b", "text": "All magnetic exposures are harmless."}, {"id": "c", "text": "Strong electromagnetic fields should be avoided."}, {"id": "d", "text": "MRI is listed as concern in note context."}, {"id": "e", "text": "Device safety teaching includes environmental risks."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment).', 'Pacemakers and ICDs - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Patient ID and symptom reporting"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Patient ID and symptom reporting"? (Select all that apply)', '[{"id": "a", "text": "Hiccups can signal diaphragm stimulation/lead displacement."}, {"id": "b", "text": "Device identification is unnecessary in emergencies."}, {"id": "c", "text": "Hiccups are always benign in this context."}, {"id": "d", "text": "Dizziness/syncope should be reported."}, {"id": "e", "text": "Pacemaker ID card is recommended."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope.', 'Pacemakers and ICDs - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "ICD function" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "ICD function" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "ICD monitors rhythm continuously."}, {"id": "b", "text": "ICD is indicated for sudden death risk patients."}, {"id": "c", "text": "ICD shocks V-fib/V-tach per note."}, {"id": "d", "text": "ICD does not treat ventricular arrhythmias."}, {"id": "e", "text": "ICD is for sinus bradycardia only."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia.', 'Pacemakers and ICDs - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "If ICD fires" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "If ICD fires" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Exercise immediately after shock is advised."}, {"id": "b", "text": "ICD firing never requires follow-up."}, {"id": "c", "text": "Lie down after ICD discharge is recommended."}, {"id": "d", "text": "Persistent symptoms require provider notification."}, {"id": "e", "text": "Documenting shock time is recommended."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: If ICD fires, patient should lie down, note time, and notify provider if symptoms continue.', 'Pacemakers and ICDs - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Bystander sensation with ICD" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Bystander sensation with ICD" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Mild shock to bystander is noted as not dangerous."}, {"id": "b", "text": "ICD discharge is fatal to bystanders."}, {"id": "c", "text": "Education reduces fear around ICD events."}, {"id": "d", "text": "Bystanders may feel mild shock."}, {"id": "e", "text": "No one near patient feels anything."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: People touching the patient during ICD discharge may feel mild shock that is not dangerous.', 'Pacemakers and ICDs - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "ICD storm emergency" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "ICD storm emergency" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Storm implies unstable arrhythmia burden."}, {"id": "b", "text": "ICD storm is routine expected function."}, {"id": "c", "text": "Immediate reporting is required."}, {"id": "d", "text": "Repeated firing is emergency."}, {"id": "e", "text": "Repeated shocks can be ignored if conscious."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Repeated ICD firing should be reported immediately as an emergency (ICD storm).', 'Pacemakers and ICDs - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Chest pain initial priorities"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Chest pain initial priorities"? (Select all that apply)', '[{"id": "a", "text": "Medications are given before ABC assessment."}, {"id": "b", "text": "ECG target is within 10 minutes."}, {"id": "c", "text": "Oxygen threshold is O2 sat <90% in note."}, {"id": "d", "text": "ABCs come first in chest pain approach."}, {"id": "e", "text": "12-lead ECG can be delayed several hours."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes.', 'Pacemakers and ICDs - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Chest pain workflow continuation" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Chest pain workflow continuation" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Aspirin then nitroglycerin then morphine/heparin sequence is listed."}, {"id": "b", "text": "No labs are needed for chest pain."}, {"id": "c", "text": "Heparin is given before aspirin."}, {"id": "d", "text": "Troponin/CK-MB/BMP are listed labs."}, {"id": "e", "text": "Large-bore IV is listed."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin.', 'Pacemakers and ICDs - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Nitroglycerin safety" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Nitroglycerin safety" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "SBP <90 is NTG hold criterion."}, {"id": "b", "text": "NTG is safe regardless of BP."}, {"id": "c", "text": "Recent sildenafil is contraindication."}, {"id": "d", "text": "Sildenafil timing has no relevance."}, {"id": "e", "text": "BP check before NTG is emphasized."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours.', 'Pacemakers and ICDs - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Positioning HF/SOB" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Positioning HF/SOB" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Breathing relief is rationale for elevated HOB."}, {"id": "b", "text": "Position has no respiratory impact."}, {"id": "c", "text": "Fowler position 30–45° is listed for HF/SOB."}, {"id": "d", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "e", "text": "Positioning reduces preload."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing.', 'Pacemakers and ICDs - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Positioning hypotension/shock" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Positioning hypotension/shock" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Sit upright is best for hypotensive shock."}, {"id": "b", "text": "Supine with legs elevated is listed for hypotension/shock."}, {"id": "c", "text": "Positioning is an early supportive intervention."}, {"id": "d", "text": "Rationale is increased venous return."}, {"id": "e", "text": "Leg lowering improves hypotension."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: For hypotension/shock, position supine with legs elevated 15–30° to increase venous return.', 'Pacemakers and ICDs - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Cardiogenic shock position caution"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Cardiogenic shock position caution"? (Select all that apply)', '[{"id": "a", "text": "Supine positioning is listed with caution."}, {"id": "b", "text": "Trendelenburg is avoided in cardiogenic shock."}, {"id": "c", "text": "Trendelenburg is first-line for cardiogenic shock."}, {"id": "d", "text": "Cardiogenic shock requires sitting upright always."}, {"id": "e", "text": "Positioning differs from routine assumptions."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg.', 'Pacemakers and ICDs - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Pericarditis and post-op positioning" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Pericarditis and post-op positioning" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Post-op position should always be Trendelenburg."}, {"id": "b", "text": "Pericarditis relieved by sit up and leaning forward."}, {"id": "c", "text": "Pericarditis is best managed flat supine."}, {"id": "d", "text": "Lung expansion is rationale for semi-Fowler post-op."}, {"id": "e", "text": "Post-cardiac surgery semi-Fowler is listed."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion.', 'Pacemakers and ICDs - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Lifestyle diet teaching" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Lifestyle diet teaching" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Fiber should be minimized."}, {"id": "b", "text": "Sodium target <2 g/day is listed."}, {"id": "c", "text": "High-sodium canned foods are recommended."}, {"id": "d", "text": "High-fiber fruits/vegetables are recommended."}, {"id": "e", "text": "Processed foods/deli meats/canned soups are discouraged."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods.', 'Pacemakers and ICDs - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lifestyle fluid/weight teaching" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Lifestyle fluid/weight teaching" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Fluid restriction 1.5–2 L/day is listed for HF."}, {"id": "b", "text": "Daily weight changes are irrelevant."}, {"id": "c", "text": "Smoking cessation and weight-loss goals are included."}, {"id": "d", "text": "Daily weight gain >2 lb should be reported."}, {"id": "e", "text": "Unlimited fluids are advised for HF."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Lifestyle instructions include no smoking, weight loss if BMI >25, fluid restriction 1.5–2 L/day in HF, and daily weight reporting if gain >2 lb.', 'Pacemakers and ICDs - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NCLEX perfusion tip" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "NCLEX perfusion tip" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Circulation support is prioritized first."}, {"id": "b", "text": "Avoid Trendelenburg in hypotension is explicit tip."}, {"id": "c", "text": "Oxygenation is prioritized first."}, {"id": "d", "text": "Documentation precedes circulation."}, {"id": "e", "text": "Trendelenburg is preferred for all hypotension."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: NCLEX tip emphasizes avoiding Trendelenburg for hypotension and prioritizing oxygenation/circulation first.', 'Pacemakers and ICDs - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Pacemaker definition"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Pacemaker definition"? (Select all that apply)', '[{"id": "a", "text": "Goal is adequate heart rate/perfusion."}, {"id": "b", "text": "Device supports contraction when intrinsic rate is insufficient."}, {"id": "c", "text": "Pacemakers only deliver defibrillation shocks."}, {"id": "d", "text": "Pacemakers deliver electrical impulses."}, {"id": "e", "text": "Pacemakers are used to raise blood volume directly."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: A pacemaker is an implanted device that delivers electrical impulses to maintain adequate heart rate and contraction.', 'Pacemakers and ICDs - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Temporary vs permanent pacing" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Temporary vs permanent pacing" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Temporary and permanent pacing have different use contexts."}, {"id": "b", "text": "Permanent systems are implanted under skin."}, {"id": "c", "text": "Temporary pacing can be used post-MI."}, {"id": "d", "text": "Permanent pacemakers are external bedside-only."}, {"id": "e", "text": "Temporary pacing is lifelong default therapy."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Temporary pacing uses external wires (e.g., acute bradycardia/post-MI), while permanent pacing is surgically implanted under skin.', 'Pacemakers and ICDs - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Bradycardia indication" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Bradycardia indication" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Asymptomatic tachycardia is primary pacing indication."}, {"id": "b", "text": "Symptomatic bradycardia is listed indication."}, {"id": "c", "text": "Symptoms drive urgency for intervention."}, {"id": "d", "text": "Bradycardia is never paced."}, {"id": "e", "text": "<60 bpm threshold appears in note context."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pacemaker indication includes symptomatic bradycardia with heart rate below 60 bpm.', 'Pacemakers and ICDs - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Heart block indication" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Heart block indication" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "AV block is contraindication to pacing."}, {"id": "b", "text": "Third-degree block is listed indication."}, {"id": "c", "text": "Electrical signal interruption between atria and ventricles is emphasized."}, {"id": "d", "text": "Second-degree type II block is listed indication."}, {"id": "e", "text": "First-degree block is the only mandatory pacing indication."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pacemaker indications include second-degree type II and third-degree AV block.', 'Pacemakers and ICDs - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Other pacing indications" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Other pacing indications" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Asystole with reversible cause is listed indication."}, {"id": "b", "text": "Sick sinus syndrome is listed indication."}, {"id": "c", "text": "Pacemaker use is excluded after cardiac surgery."}, {"id": "d", "text": "Post-cardiac surgery prophylaxis is listed use."}, {"id": "e", "text": "Only ventricular tachycardia is paced."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Other listed pacing indications include asystole with reversible cause, sick sinus syndrome, and post-cardiac surgery prophylaxis.', 'Pacemakers and ICDs - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "ECG post-implant monitoring"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "ECG post-implant monitoring"? (Select all that apply)', '[{"id": "a", "text": "Pacing spikes should be visible/appropriate."}, {"id": "b", "text": "ECG is unnecessary after implant."}, {"id": "c", "text": "Spikes indicate malfunction by default."}, {"id": "d", "text": "ECG monitoring is immediate post-implant priority."}, {"id": "e", "text": "Rhythm verification is central to pacemaker safety."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Nursing care includes ECG monitoring to verify pacing spikes and appropriate response.', 'Pacemakers and ICDs - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Pacing threshold" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Pacing threshold" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Threshold is the maximum tolerated blood pressure."}, {"id": "b", "text": "Threshold has no relation to pacing effectiveness."}, {"id": "c", "text": "Threshold assessment is listed nursing priority."}, {"id": "d", "text": "Capture reliability depends on adequate output above threshold."}, {"id": "e", "text": "Threshold refers to minimum effective current."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pacing threshold is the lowest current needed to pace the heart.', 'Pacemakers and ICDs - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Failure to pace" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Failure to pace" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "No pacing spike can indicate failure to pace."}, {"id": "b", "text": "Failure to pace shows spike with no QRS."}, {"id": "c", "text": "Failure to pace is normal after implantation."}, {"id": "d", "text": "Immediate troubleshooting is required when no spike appears."}, {"id": "e", "text": "Expected pacing without spike is abnormal."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Failure to pace is identified by absence of pacing spike when one is expected.', 'Pacemakers and ICDs - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Failure to capture" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Failure to capture" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Failure to capture means no spike present."}, {"id": "b", "text": "Spike without QRS defines failure to capture."}, {"id": "c", "text": "Capture failure threatens perfusion."}, {"id": "d", "text": "Electrical output without depolarization is abnormal."}, {"id": "e", "text": "Spike followed by QRS always indicates failure."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Failure to capture is pacing spike without resulting QRS complex.', 'Pacemakers and ICDs - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Arm movement restriction" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Arm movement restriction" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Arm restriction duration is 24–48 hours."}, {"id": "b", "text": "Arm restriction is unnecessary after implant."}, {"id": "c", "text": "Reason is prevention of lead displacement."}, {"id": "d", "text": "Aggressive overhead arm exercise is encouraged immediately."}, {"id": "e", "text": "Post-op mobility guidance is part of nursing care."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: After implant, restrict affected arm movement for 24–48 hours to prevent lead displacement.', 'Pacemakers and ICDs - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Electromagnetic precautions"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Electromagnetic precautions"? (Select all that apply)', '[{"id": "a", "text": "Strong electromagnetic fields should be avoided."}, {"id": "b", "text": "MRI is listed as concern in note context."}, {"id": "c", "text": "Arc welding is recommended with pacemakers."}, {"id": "d", "text": "Device safety teaching includes environmental risks."}, {"id": "e", "text": "All magnetic exposures are harmless."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Patients should avoid strong electromagnetic fields (e.g., MRI, arc welding, certain equipment).', 'Pacemakers and ICDs - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Patient ID and symptom reporting" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Patient ID and symptom reporting" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Pacemaker ID card is recommended."}, {"id": "b", "text": "Hiccups can signal diaphragm stimulation/lead displacement."}, {"id": "c", "text": "Dizziness/syncope should be reported."}, {"id": "d", "text": "Device identification is unnecessary in emergencies."}, {"id": "e", "text": "Hiccups are always benign in this context."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Patients should carry pacemaker ID card and report hiccups, dizziness, or syncope.', 'Pacemakers and ICDs - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "ICD function" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "ICD function" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "ICD is for sinus bradycardia only."}, {"id": "b", "text": "ICD does not treat ventricular arrhythmias."}, {"id": "c", "text": "ICD monitors rhythm continuously."}, {"id": "d", "text": "ICD shocks V-fib/V-tach per note."}, {"id": "e", "text": "ICD is indicated for sudden death risk patients."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: ICD continuously monitors rhythm and delivers shock for ventricular fibrillation or ventricular tachycardia.', 'Pacemakers and ICDs - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "If ICD fires" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "If ICD fires" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Documenting shock time is recommended."}, {"id": "b", "text": "ICD firing never requires follow-up."}, {"id": "c", "text": "Exercise immediately after shock is advised."}, {"id": "d", "text": "Lie down after ICD discharge is recommended."}, {"id": "e", "text": "Persistent symptoms require provider notification."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: If ICD fires, patient should lie down, note time, and notify provider if symptoms continue.', 'Pacemakers and ICDs - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Bystander sensation with ICD" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Bystander sensation with ICD" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Education reduces fear around ICD events."}, {"id": "b", "text": "Mild shock to bystander is noted as not dangerous."}, {"id": "c", "text": "ICD discharge is fatal to bystanders."}, {"id": "d", "text": "No one near patient feels anything."}, {"id": "e", "text": "Bystanders may feel mild shock."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: People touching the patient during ICD discharge may feel mild shock that is not dangerous.', 'Pacemakers and ICDs - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "ICD storm emergency"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "ICD storm emergency"? (Select all that apply)', '[{"id": "a", "text": "Storm implies unstable arrhythmia burden."}, {"id": "b", "text": "Repeated firing is emergency."}, {"id": "c", "text": "ICD storm is routine expected function."}, {"id": "d", "text": "Immediate reporting is required."}, {"id": "e", "text": "Repeated shocks can be ignored if conscious."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Repeated ICD firing should be reported immediately as an emergency (ICD storm).', 'Pacemakers and ICDs - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Chest pain initial priorities" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Chest pain initial priorities" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Medications are given before ABC assessment."}, {"id": "b", "text": "12-lead ECG can be delayed several hours."}, {"id": "c", "text": "ECG target is within 10 minutes."}, {"id": "d", "text": "Oxygen threshold is O2 sat <90% in note."}, {"id": "e", "text": "ABCs come first in chest pain approach."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Chest pain protocol starts with ABC assessment, oxygen if saturation <90%, vitals, and 12-lead ECG within 10 minutes.', 'Pacemakers and ICDs - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Chest pain workflow continuation" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Chest pain workflow continuation" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Large-bore IV is listed."}, {"id": "b", "text": "Heparin is given before aspirin."}, {"id": "c", "text": "Aspirin then nitroglycerin then morphine/heparin sequence is listed."}, {"id": "d", "text": "Troponin/CK-MB/BMP are listed labs."}, {"id": "e", "text": "No labs are needed for chest pain."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Protocol includes large-bore IV access, labs (troponin, CK-MB, BMP), and meds sequence: aspirin, nitroglycerin, morphine if needed, then heparin.', 'Pacemakers and ICDs - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Nitroglycerin safety" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Nitroglycerin safety" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "SBP <90 is NTG hold criterion."}, {"id": "b", "text": "NTG is safe regardless of BP."}, {"id": "c", "text": "Sildenafil timing has no relevance."}, {"id": "d", "text": "Recent sildenafil is contraindication."}, {"id": "e", "text": "BP check before NTG is emphasized."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Check blood pressure before nitroglycerin; avoid nitroglycerin if systolic BP <90 or recent sildenafil use within 24–48 hours.', 'Pacemakers and ICDs - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Positioning HF/SOB" in Pacemakers & ICDs are correct? (Select all that apply)', 'Which statements about "Positioning HF/SOB" in Pacemakers & ICDs are correct? (Select all that apply)', '[{"id": "a", "text": "Fowler position 30–45° is listed for HF/SOB."}, {"id": "b", "text": "Positioning reduces preload."}, {"id": "c", "text": "Flat Trendelenburg is best for HF/SOB."}, {"id": "d", "text": "Breathing relief is rationale for elevated HOB."}, {"id": "e", "text": "Position has no respiratory impact."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: For heart failure/SOB, best position is HOB elevated 30–45° (Fowler) to reduce preload and ease breathing.', 'Pacemakers and ICDs - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pacemakers & ICDs, which findings or actions relate to "Positioning hypotension/shock"? (Select all that apply)', 'For Pacemakers & ICDs, which findings or actions relate to "Positioning hypotension/shock"? (Select all that apply)', '[{"id": "a", "text": "Sit upright is best for hypotensive shock."}, {"id": "b", "text": "Leg lowering improves hypotension."}, {"id": "c", "text": "Rationale is increased venous return."}, {"id": "d", "text": "Supine with legs elevated is listed for hypotension/shock."}, {"id": "e", "text": "Positioning is an early supportive intervention."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: For hypotension/shock, position supine with legs elevated 15–30° to increase venous return.', 'Pacemakers and ICDs - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Cardiogenic shock position caution" in Pacemakers & ICDs? (Select all that apply)', 'The nurse is planning care. Which items apply to "Cardiogenic shock position caution" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Positioning differs from routine assumptions."}, {"id": "b", "text": "Trendelenburg is first-line for cardiogenic shock."}, {"id": "c", "text": "Trendelenburg is avoided in cardiogenic shock."}, {"id": "d", "text": "Cardiogenic shock requires sitting upright always."}, {"id": "e", "text": "Supine positioning is listed with caution."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: For cardiogenic shock, note recommends supine with caution and to avoid Trendelenburg.', 'Pacemakers and ICDs - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Pericarditis and post-op positioning" in Pacemakers & ICDs? (Select all that apply)', 'Which of the following are consistent with "Pericarditis and post-op positioning" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "Post-op position should always be Trendelenburg."}, {"id": "b", "text": "Pericarditis relieved by sit up and leaning forward."}, {"id": "c", "text": "Pericarditis is best managed flat supine."}, {"id": "d", "text": "Post-cardiac surgery semi-Fowler is listed."}, {"id": "e", "text": "Lung expansion is rationale for semi-Fowler post-op."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis position is sit up/lean forward; post-cardiac surgery preferred is semi-Fowler for comfort and lung expansion.', 'Pacemakers and ICDs - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lifestyle diet teaching" in Pacemakers & ICDs? (Select all that apply)', 'During reassessment, which observations align with "Lifestyle diet teaching" in Pacemakers & ICDs? (Select all that apply)', '[{"id": "a", "text": "High-fiber fruits/vegetables are recommended."}, {"id": "b", "text": "Fiber should be minimized."}, {"id": "c", "text": "Sodium target <2 g/day is listed."}, {"id": "d", "text": "High-sodium canned foods are recommended."}, {"id": "e", "text": "Processed foods/deli meats/canned soups are discouraged."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Diet teaching includes sodium restriction <2 g/day, low saturated fat/cholesterol, high fiber/fruits/vegetables, and avoiding processed high-salt foods.', 'Pacemakers and ICDs - NCLEX', true, 100, 1, true);
